    def is_market_symbol_cached(self, symbol: str) -> bool:
        if self.markets is None:
            return False
        return symbol in self.markets

    def remove_cached_market_symbol(self, symbol: str):
        if self.markets is None:
            return
        if symbol in self.markets:
            del self.markets[symbol]

    def merge_markets(self, newMarkets: List[Market]):
        existingMarkets = [] if (self.markets is None) else list(self.markets.values())
        combined = self.array_concat(existingMarkets, newMarkets)
        self.set_markets(combined)

    def cache_rate_for_symbol(self, symbol: str, rate: dict):
        cachedRateBySymbol = self.safe_dict(self.options, 'cachedRateBySymbol', {})
        cachedRateBySymbol[symbol] = rate
        self.options['cachedRateBySymbol'] = cachedRateBySymbol

    def get_cached_rate_for_symbol(self, symbol: str) -> dict:
        cachedRateBySymbol = self.safe_dict(self.options, 'cachedRateBySymbol', {})
        return self.safe_dict(cachedRateBySymbol, symbol, {})

    async def request_new_rate(self, symbol: str, params={}) -> dict:
        self.check_required_credentials()
        parsed = self.parse_market_symbol(symbol)
        amountFrom = self.safe_string(params, 'amount_from', '0.01')
        request: dict = {
            'ticker_from': self.safe_string(parsed, 'tickerFrom'),
            'network_from': self.safe_string(parsed, 'networkFrom'),
            'ticker_to': self.safe_string(parsed, 'tickerTo'),
            'network_to': self.safe_string(parsed, 'networkTo'),
            'amount_from': amountFrom,
            'best_only': True,
        }
        callParams = self.omit(params, ['amount_from'])
        response = await self.publicGetNewRate(self.extend(request, callParams))
        if response is None or not isinstance(response, dict):
            raise BadSymbol(self.id + ' does not have market ' + symbol)
        amountTo = self.safe_string(response, 'amount_to')
        if amountTo is None:
            raise BadSymbol(self.id + ' does not have market ' + symbol)
        self.cache_rate_for_symbol(symbol, response)
        return response

    async def resolve_markets(self, symbols: List[str], params={}) -> dict:
        marketsBySymbol: dict = {}
        pendingSymbols = []
        newMarkets: List[Market] = []
        marketsDict = {} if (self.markets is None) else self.markets
        for symbolIndex in range(0, len(symbols)):
            symbol = symbols[symbolIndex]
            if symbol in marketsDict:
                marketsBySymbol[symbol] = self.market(symbol)
                continue
            pendingSymbols.append(symbol)
        for pendingIndex in range(0, len(pendingSymbols)):
            symbol = pendingSymbols[pendingIndex]
            await self.request_new_rate(symbol, params)
            market = self.parse_market_from_symbol(symbol)
            newMarkets.append(market)
            marketsBySymbol[symbol] = market
        if len(newMarkets) > 0:
            self.merge_markets(newMarkets)
            for pendingIndex in range(0, len(pendingSymbols)):
                symbol = pendingSymbols[pendingIndex]
                marketsBySymbol[symbol] = self.market(symbol)
        return {
            'marketsBySymbol': marketsBySymbol,
        }

    async def resolve_market(self, symbol: str, params={}) -> Market:
        resolveResult = await self.resolve_markets([symbol], params)
        return resolveResult['marketsBySymbol'][symbol]

    async def fetch_currencies(self, params={}) -> Currencies:
        """
        fetches all available currencies on Trocador

        https://trocador.app/en/docs/

        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: an associative dictionary of currencies
        """
        self.check_required_credentials()
        response = await self.publicGetCoins(params)
        coins = self.to_array(response)
        result: dict = {}
        for coinIndex in range(0, len(coins)):
            coin = coins[coinIndex]
            ticker = self.safe_string(coin, 'ticker')
            network = self.safe_string(coin, 'network')
            if ticker is None or network is None:
                continue
            currencyId = ticker.lower() + '@' + network.lower()
            code = self.safe_currency_code(ticker)
            minimum = self.safe_number(coin, 'minimum')
            maximum = self.safe_number(coin, 'maximum')
            memo = self.safe_bool(coin, 'memo', False)
            result[code] = self.safe_currency_structure({
                'id': currencyId,
                'code': code,
                'name': self.safe_string(coin, 'name'),
                'active': True,
                'deposit': True,
                'withdraw': True,
                'fee': None,
                'precision': None,
                'limits': {
                    'amount': {'min': minimum, 'max': maximum},
                    'withdraw': {'min': minimum, 'max': maximum},
                },
                'info': self.extend(coin, {'memo': memo}),
            })
        return result

    async def fetch_markets(self, params={}) -> List[Market]:
        """
        fetches markets; returns empty by default(markets loaded on demand)

        https://trocador.app/en/docs/

        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns Market[]: an array of market structures
        """
        return []

    async def ob_load_markets_for_symbols(self, symbols: List[str], reload=False, params={}) -> List[dict]:
        """
        lazily resolves and populates self.markets for the given symbols

        https://trocador.app/en/docs/

        :param str[] symbols: list of unified market symbols
        :param boolean reload: when True, re-fetch symbols even if already cached in self.markets
        :param dict params: extra parameters specific to the exchange API endpoint
        :returns dict[]: empty list; ob_trocador returns fixed market status structures
        """
        if symbols is None:
            raise ArgumentsRequired(self.id + ' obLoadMarketsForSymbols() requires a non-empty symbols argument')
        symbolsLength = len(symbols)
        if symbolsLength == 0:
            raise ArgumentsRequired(self.id + ' obLoadMarketsForSymbols() requires a non-empty symbols argument')
        await self.load_markets()
        symbolsToResolve = []
        for symbolIndex in range(0, symbolsLength):
            symbol = symbols[symbolIndex]
            if reload:
                self.remove_cached_market_symbol(symbol)
                symbolsToResolve.append(symbol)
            elif not self.is_market_symbol_cached(symbol):
                symbolsToResolve.append(symbol)
        if len(symbolsToResolve) > 0:
            await self.resolve_markets(symbolsToResolve, params)
        return []

    async def fetch_ticker(self, symbol: str, params={}) -> Ticker:
        """
        fetches a price ticker / estimate for a swap pair on Trocador

        https://trocador.app/en/docs/

        :param str symbol: unified market symbol, e.g. 'BTC@Mainnet/XMR@Mainnet'
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param str [params.amount_from]: amount to estimate, defaults to '0.01'
        :returns dict: a `ticker structure <https://docs.ccxt.com/?id=ticker-structure>`
        """
        await self.load_markets()
        resolveResult = await self.resolve_markets([symbol], params)
        market = resolveResult['marketsBySymbol'][symbol]
        amountFrom = self.safe_string(params, 'amount_from', '0.01')
        callParams = self.omit(params, ['amount_from'])
        response = await self.request_new_rate(symbol, self.extend({'amount_from': amountFrom}, callParams))
        return self.parse_ticker(response, market)

    def parse_ticker(self, ticker: dict, market: Market = None) -> Ticker:
        symbol = self.safe_string(market, 'symbol')
        last = self.safe_string(ticker, 'amount_to')
        return self.safe_ticker({
            'symbol': symbol,
            'timestamp': None,
            'datetime': None,
            'high': None,
            'low': None,
            'bid': last,
            'bidVolume': None,
            'ask': last,
            'askVolume': None,
            'vwap': None,
            'open': None,
            'close': last,
            'last': last,
            'previousClose': None,
            'change': None,
            'percentage': None,
            'average': None,
            'baseVolume': None,
            'quoteVolume': None,
            'info': ticker,
        }, market)

    async def create_order(self, symbol: str, type: OrderType, side: OrderSide, amount: float, price: Num = None, params={}) -> Order:
        """
        create a swap order on Trocador(requires API key)

        https://trocador.app/en/docs/

        :param str symbol: unified market symbol, e.g. 'BTC@Mainnet/XMR@Mainnet'
        :param str type: order type – 'market' for floating rate, 'limit' for fixed rate
        :param str side: 'buy' or 'sell' – for swaps self is always 'sell'(sell base for quote)
        :param float amount: amount of the base currency to send
        :param float [price]: not used for Trocador
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param str params['address_to']: destination address for the quote currency(required)
        :param str [params.extraId]: memo/ExtraID for the destination address('0' when unused)
        :param str [params.refund_address]: refund address for the base currency
        :param str [params.refundExtraId]: memo/ExtraID for the refund address('0' when unused)
        :param str [params.provider]: aggregator provider from the quote(defaults to cached best quote)
        :param bool [params.fixed]: fixed-rate flag from the quote(defaults to cached best quote)
        :param str [params.rateId]: rate id from new_rate(defaults to cached trade_id)
        :returns dict: an `order structure <https://docs.ccxt.com/?id=order-structure>`
        """
        self.check_required_credentials()
        await self.load_markets()
        resolveResult = await self.resolve_markets([symbol], params)
        market = resolveResult['marketsBySymbol'][symbol]
        parsed = self.parse_market_symbol(symbol)
        addressTo = self.safe_string(params, 'address_to')
        if addressTo is None:
            raise ArgumentsRequired(self.id + ' createOrder() requires params.address_to – the destination address for the received currency')
        cachedRate = self.get_cached_rate_for_symbol(symbol)
        rateId = self.safe_string(params, 'rateId')
        if rateId is not None or self.is_empty(cachedRate):
            cachedRate = await self.request_new_rate(symbol, self.extend({'amount_from': self.number_to_string(amount)}, params))
        provider = self.safe_string(params, 'provider')
        if provider is None:
            provider = self.safe_string(cachedRate, 'provider')
        if provider is None:
            raise ArgumentsRequired(self.id + ' createOrder() requires params.provider or a prior fetchTicker/new_rate quote with provider')
        fixed = self.safe_bool(params, 'fixed')
        if fixed is None:
            fixed = self.safe_bool(cachedRate, 'fixed')
        if fixed is None:
            fixed = (type == 'limit')
        tradeId = self.safe_string_2(params, 'rateId', 'id')
        request: dict = {
            'ticker_from': self.safe_string(parsed, 'tickerFrom'),
            'network_from': self.safe_string(parsed, 'networkFrom'),
            'ticker_to': self.safe_string(parsed, 'tickerTo'),
            'network_to': self.safe_string(parsed, 'networkTo'),
            'amount_from': self.number_to_string(amount),
            'address': addressTo,
            'provider': provider,
            'fixed': fixed,
        }
        resolvedRateId = tradeId if (tradeId is not None) else self.safe_string(cachedRate, 'trade_id')
        if resolvedRateId is not None:
            request['id'] = resolvedRateId
        extraId = self.safe_string(params, 'extraId', '0')
        request['address_memo'] = extraId
        refundAddress = self.safe_string(params, 'refund_address')
        if refundAddress is not None:
            request['refund'] = refundAddress
            refundExtraId = self.safe_string(params, 'refundExtraId', '0')
            request['refund_memo'] = refundExtraId
        callParams = self.omit(params, ['address_to', 'extraId', 'refund_address', 'refundExtraId', 'provider', 'fixed', 'rateId', 'id', 'amount_from'])
        response = await self.publicPostNewTrade(self.extend(request, callParams))
        return self.parse_order(response, market)

    def parse_trade_response(self, response, id: str) -> dict:
        if response is None or response == None or response == False:
            raise OrderNotFound(self.id + ' order ' + id + ' not found')
        if isinstance(response, list):
            if len(response) == 1:
                response = response[0]
            else:
                raise OrderNotFound(self.id + ' order ' + id + ' not found')
        if not isinstance(response, dict):
            raise OrderNotFound(self.id + ' order ' + id + ' not found')
        responseStatus = self.safe_string(response, 'status')
        if responseStatus is None:
            raise OrderNotFound(self.id + ' order ' + id + ' not found')
        return response

    async def fetch_order(self, id: str, symbol: Str = None, params={}) -> Order:
        """
        fetch the status of a Trocador swap order

        https://trocador.app/en/docs/

        :param str id: the order / trade id
        :param str [symbol]: unified market symbol(optional)
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: an `order structure <https://docs.ccxt.com/?id=order-structure>`
        """
        self.check_required_credentials()
        request: dict = {
            'id': id,
        }
        response = None
        try:
            response = await self.publicGetTrade(self.extend(request, params))
        except Exception as e:
            if isinstance(e, OrderNotFound):
                raise e
            if isinstance(e, AuthenticationError):
                raise e
            raise OrderNotFound(self.id + ' order ' + id + ' not found')
        trade = self.parse_trade_response(response, id)
        return self.parse_order(trade)

    def parse_order(self, order: dict, market: Market = None) -> Order:
        id = self.safe_string_2(order, 'trade_id', 'id')
        tickerFrom = self.safe_string(order, 'ticker_from')
        tickerTo = self.safe_string(order, 'ticker_to')
        networkFrom = self.safe_string(order, 'network_from')
        networkTo = self.safe_string(order, 'network_to')
        parsedSymbol = None
        if tickerFrom is not None and tickerTo is not None and networkFrom is not None and networkTo is not None:
            baseCode = self.safe_currency_code(tickerFrom)
            quoteCode = self.safe_currency_code(tickerTo)
            parsedSymbol = baseCode + '@' + networkFrom + '/' + quoteCode + '@' + networkTo
        symbol = self.safe_string(market, 'symbol')
        if symbol is None:
            symbol = parsedSymbol
        rawStatus = self.safe_string(order, 'status')
        status = None
        if rawStatus is not None:
            status = self.parse_order_status(rawStatus)
        else:
            status = 'open'
        amountFrom = self.safe_string(order, 'amount_from')
        amountTo = self.safe_string(order, 'amount_to')
        timestampStr = self.safe_string(order, 'date')
        timestamp = None
        if timestampStr is not None:
            timestamp = self.parse8601(timestampStr.replace(' ', 'T') + 'Z')
        return self.safe_order({
            'id': id,
            'clientOrderId': None,
            'info': order,
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'lastTradeTimestamp': None,
            'lastUpdateTimestamp': None,
            'symbol': symbol,
            'type': 'limit' if self.safe_bool(order, 'fixed', False) else 'market',
            'timeInForce': None,
            'postOnly': None,
            'side': 'sell',
            'price': amountTo,
            'stopPrice': None,
            'triggerPrice': None,
            'amount': amountFrom,
            'cost': None,
            'average': None,
            'filled': None,
            'remaining': None,
            'status': status,
            'fee': {
                'currency': None,
                'cost': None,
                'rate': None,
            },
            'trades': None,
        }, market)

    def parse_order_status(self, status: Str) -> Str:
        statuses: dict = self.safe_dict(self.options, 'statusMapping', {})
        return self.safe_string(statuses, status, status)

    def sign(self, path, api='public', method='GET', params={}, headers=None, body=None):
        self.check_required_credentials(False)
        apiKey = self.resolve_api_key()
        url = self.urls['api']['rest'] + '/' + path
        query = self.omit(params, self.extract_params(path))
        if method == 'GET':
            if query:
                url += '?' + self.urlencode(query)
        elif method == 'POST':
            if query:
                body = self.json(query)
                headers = {
                    'Content-Type': 'application/json',
                }
        authHeaders: dict = {
            'API-Key': apiKey,
        }
        if headers is not None:
            authHeaders['Content-Type'] = self.safe_string(headers, 'Content-Type')
        return {'url': url, 'method': method, 'body': body, 'headers': authHeaders}

    def handle_errors(self, httpCode: int, reason: str, url: str, method: str, headers: dict, body: str, response, requestHeaders, requestBody):
        if httpCode == 401 or httpCode == 403:
            raise AuthenticationError(self.id + ' ' + body)
        if httpCode == 404 and url.find('/trade') >= 0:
            raise OrderNotFound(self.id + ' order not found')
        if response is None:
            return None
        error = self.safe_string(response, 'error')
        message = self.safe_string(response, 'message')
        if error is not None:
            raise ExchangeError(self.id + ' ' + body)
        if message is not None and httpCode >= 400:
            if httpCode == 401 or httpCode == 403:
                raise AuthenticationError(self.id + ' ' + body)
            raise BadRequest(self.id + ' ' + body)
        return None
